# Epilogue for CR-001
out_dir <- "/work/out"
if (!dir.exists(out_dir)) dir.create(out_dir, recursive = TRUE)
# Verify required objects
required <- c("sc","Xs","pd","decision","cf","fit")
missing <- required[!sapply(required, exists, inherits = FALSE)]
if (length(missing) > 0) {
  stop(paste("Missing required object(s):", paste(missing, collapse=", ")))
}
# 1. frame.csv – raw inputs
frame <- sc
frame$.row <- seq_len(nrow(frame))
write.csv(frame, file = file.path(out_dir, "frame.csv"), row.names = FALSE)
# 2. scores.csv – predictions and decision
scores <- data.frame(.row = seq_len(length(pd)), score = pd, stringsAsFactors = FALSE)
if (exists("decision", inherits = FALSE)) {
  scores$decision <- decision
}
write.csv(scores, file = file.path(out_dir, "scores.csv"), row.names = FALSE)
# 3. coef.csv – model coefficients
if (exists("cf", inherits = FALSE)) {
  coef_df <- data.frame(term = names(cf), estimate = unname(cf), stringsAsFactors = FALSE)
} else {
  coef_vec <- coef(fit)
  coef_df <- data.frame(term = names(coef_vec), estimate = unname(coef_vec), stringsAsFactors = FALSE)
}
write.csv(coef_df, file = file.path(out_dir, "coef.csv"), row.names = FALSE)
# 4. train_rows.csv – per instruction write Xs
write.csv(Xs, file = file.path(out_dir, "train_rows.csv"), row.names = FALSE)
cat("Export completed successfully.\n")
